namespace RenoTrack.Application.Common.Documents;

/// <summary>
/// The file name an issued invoice's PDF carries wherever it leaves the system — the Admin's
/// download and the email attachment (Phase 14 Slice 3a, <b>D113</b>). One definition, so the file a
/// customer receives and the file an Admin downloads cannot be named differently.
/// </summary>
/// <remarks>
/// <para>
/// <b>Allowlist-shaped.</b> The invoice number is generated by the server (<c>RE-2026-00017</c>), so
/// nothing a caller types reaches this name today. It still lands in a <c>Content-Disposition</c>
/// header and a MIME part, so every character outside <c>[A-Za-z0-9-]</c> is replaced rather than
/// trusted: a quote, a semicolon or a line break can never break out of either.
/// </para>
/// </remarks>
public static class InvoiceDocumentFileName
{
    /// <summary>The media type of every generated document.</summary>
    public const string PdfContentType = "application/pdf";

    /// <summary><c>Rechnung-RE-2026-00017.pdf</c> for invoice <c>RE-2026-00017</c>.</summary>
    public static string For(string invoiceNumber)
    {
        ArgumentNullException.ThrowIfNull(invoiceNumber);

        var safe = new string(invoiceNumber
            .Trim()
            .Select(character => char.IsAsciiLetterOrDigit(character) || character == '-' ? character : '-')
            .ToArray());

        return safe.Length == 0 ? "Rechnung.pdf" : $"Rechnung-{safe}.pdf";
    }
}
